use vstd::prelude::*;

verus! {

fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@.len() == arr@.len() + values@.len(),
        forall|i: int| 0 <= i < arr@.len() ==> result@[i] == arr@[i],
        forall|j: int| 0 <= j < values@.len() ==> result@[arr@.len() + j] == values@[j],
{
    let arr_len = arr.len();
    let vals_len = values.len();

    let mut res: Vec<f32> = Vec::with_capacity(arr_len + vals_len);

    // Append arr
    let mut i: usize = 0;
    while i < arr_len
        invariant
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == arr@[k],
        decreases arr_len - i,
    {
        res.push(arr[i]);
        i += 1;
    }

    // Append values
    let mut j: usize = 0;
    while j < vals_len
        invariant
            res@.len() == arr@.len() + j as int,
            forall|k: int| 0 <= k < arr@.len() ==> res@[k] == arr@[k],
            forall|k: int| 0 <= k < j as int ==> res@[arr@.len() + k] == values@[k],
        decreases vals_len - j,
    {
        res.push(values[j]);
        j += 1;
    }

    res
}

} // verus!

